+func TestRegistryDuplicateDetectionInSameBatch(t *testing.T) {
+	r := &TypeRegistry{}
+	
+	spec1 := &TypeSpec{Name: "first", T: "duplicate_t"}
+	spec2 := &TypeSpec{Name: "second", T: "duplicate_t"} // Same T as spec1
+	
+	err := r.Register(spec1, spec2)
+	require.Error(t, err)
+	require.Contains(t, err.Error(), `specutil: type with T of "duplicate_t" already registered`)
+	
+	// Test that it works with unique T values
+	r2 := &TypeRegistry{}
+	spec3 := &TypeSpec{Name: "third", T: "unique_t1"}
+	spec4 := &TypeSpec{Name: "fourth", T: "unique_t2"} // Different T
+	
+	err = r2.Register(spec3, spec4)
+	require.NoError(t, err)
+}
